      - pre-commit run --all-files --show-diff-on-failure
  "Unit Tests": { vm: full, repro: ["./scripts/local_run_backend_unit_tests.sh client <failed test label>"] }
  "I&T - AWS": { hand_off: "qa-on-prem behind client_integration_tests_aws" }
  "I&T - GCP": { hand_off: "behind client_integration_tests_gcp" }

// ai-agents/harness/src/checks/false-heal.ts: sketch; G0's locked-checks detector plus the charter rules
const TEST_FILE = /(^|\/)(tests?|e2e|integration-tests)\/|(^|\/)test_[^/]*\.py$|_test\.py$|\.(test|spec)\.tsx?$/;
const SKIP = /@pytest\.mark\.(skip|xfail)|@unittest\.skip|self\.skipTest\(|\b(it|test|describe)\.(skip|only|fixme)\(/;
const ASSERT = /\bassert\b|self\.assert\w+\(|\bexpect\(/;
const THRESHOLD = /(fail[-_]under|retries|timeout\w*)\s*[:=]\s*([\d.]+)/i;
const RETRY_OR_SLEEP = /time\.sleep\(|asyncio\.sleep\(|@retry|@flaky|--reruns|waitForTimeout\(/;
const count = (rx: RegExp, lines: string[]): number => lines.filter((line) => rx.test(line)).length;

export function falseHeals(diff: FileDiff[], never: Set<string>): string[] {
  const found: string[] = [];
  for (const f of diff) {
    const isTest = TEST_FILE.test(f.path);
    if (f.deleted && isTest) found.push(`${f.path}: test file deleted`);
    found.push(...f.added.filter((line) => SKIP.test(line)).map((line) => `${f.path}: new skip \`${line.trim()}\``));
    if (isTest) {
      const removed = count(ASSERT, f.removed), added = count(ASSERT, f.added);
      if (removed > added) found.push(`${f.path}: ${removed - added} assertion(s) removed`);
      if (never.has("edit_test_assertions") && removed) found.push(`${f.path}: an existing assertion was changed`);
    }

    for (const [key, oldValue, newValue] of pairedChanges(THRESHOLD, f)) {  // the same key on a removed and an added line
      const loosened = key.toLowerCase().includes("fail") ? newValue < oldValue : newValue > oldValue;
      if (loosened) found.push(`${f.path}: ${key} loosened ${oldValue} -> ${newValue}`);
    }
    if (never.has("add_retries_or_sleeps")) {
      found.push(...f.added.filter((line) => RETRY_OR_SLEEP.test(line)).map(() => `${f.path}: retry or sleep added`));
    }
    if (never.has("add_code") && !onlyRemovesTokens(f)) {  // dead-code removers may only delete
      found.push(`${f.path}: new code in a deletions-only routine`);
    }
  }
  return found;  // any finding → outcome false_heal: rejected, and counted on the trust ladder (G5-15)
}

// ai-agents/harness/src/checks/false-heal-workflows.ts: sketch: extra false-heal rules for workflow files
import { parse } from "yaml";

const WEAKENERS: [RegExp, string][] = [
  [/^\s*continue-on-error:\s*true/, "continue-on-error added"],
  [/^\s*if:\s*(false|\$\{\{\s*false\s*\}\})\s*$/, "job or step switched off"],
  [/\|\|\s*(true|exit 0)\s*$/, "failure swallowed with || true"],
  [/-check=false|--no-verify|--exit-code[ =]0/, "check flag turned off"],
];

export function workflowFalseHeals(diff: FileDiff[], requiredChecks: Set<string>): string[] {
  const found: string[] = [];
  for (const f of diff) {
    if (!f.path.startsWith(".github/workflows/")) continue;
    for (const line of f.added) {
      found.push(...WEAKENERS.filter(([rx]) => rx.test(line)).map(([, why]) => `${f.path}: ${why}`));
    }
    const before = jobNames(f.oldText), after = jobNames(f.newText);
    for (const name of before) {  // required checks come from the ruleset (G0)
      if (!after.has(name) && requiredChecks.has(name)) found.push(`${f.path}: removed required check '${name}'`);
    }

    const oldPaths = triggerPaths(f.oldText), newPaths = triggerPaths(f.newText);
    if (newPaths.size < oldPaths.size && [...newPaths].every((p) => oldPaths.has(p))) {
      found.push(`${f.path}: trigger paths narrowed, so the check stops running on some changes`);
    }
  }
  return found;  // merged with falseHeals() (G5-14); any finding rejects the run
}

function jobNames(text: string): Set<string> {  // parsed with the yaml package; a job's check name is name: or its id
  const jobs: Record<string, { name?: string }> = parse(text)?.jobs ?? {};
  return new Set(Object.entries(jobs).map(([id, job]) => job.name ?? id));
}

