export interface FileDiff { path: string; deleted: boolean; added: string[]; removed: string[] }

/** Read a unified diff (git diff output) into one entry per file. Enough for the false-heal check. */
export function parseDiff(text: string): FileDiff[] {
  const files: FileDiff[] = [];
  let f: FileDiff | undefined;
  for (const line of text.split("\n")) {
    const head = /^diff --git a\/(\S+) b\//.exec(line);
    if (head) { f = { path: head[1], deleted: false, added: [], removed: [] }; files.push(f); continue; }
    if (!f || line.startsWith("+++") || line.startsWith("---")) continue;
    if (line.startsWith("deleted file mode")) f.deleted = true;
    else if (line.startsWith("+")) f.added.push(line.slice(1));
    else if (line.startsWith("-")) f.removed.push(line.slice(1));
  }
  return files;
}

/** [key, old, new] for every threshold whose key appears on a removed line and on an added line. */
export function pairedChanges(rx: RegExp, f: FileDiff): [string, number, number][] {
  const values = (lines: string[]) => new Map(lines.map((l) => rx.exec(l)).filter((m) => m !== null).map((m) => [m[1], Number(m[2])]));
  const before = values(f.removed), after = values(f.added);
  return [...before].filter(([key]) => after.has(key)).map(([key, old]) => [key, old, after.get(key)!]);
}

/** True when every added line is a removed line with some names taken out, e.g. a shorter import. */
export function onlyRemovesTokens(f: FileDiff): boolean {
  const words = (l: string) => l.match(/\w+/g) ?? [];
  return f.added.every((a) => f.removed.some((r) => words(a).every((w) => words(r).includes(w))));
}

