import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { parseDiff } from "../src/diff.js";
import { falseHeals } from "../src/false-heal.js";

const fixture = (name: string) => parseDiff(readFileSync(new URL(`./fixtures/${name}.diff`, import.meta.url), "utf8"));
const CI_FIXER = new Set(["edit_test_assertions"]);
const FLAKY_FIXER = new Set(["add_retries_or_sleeps", "edit_test_assertions"]);

test("an honest fix has no findings", () => {
  assert.deepEqual(falseHeals(fixture("honest-fix"), CI_FIXER), []);
});
test("a deleted test file is a false heal", () => {
  assert.match(falseHeals(fixture("deleted-test"), CI_FIXER).join("\n"), /test file deleted/);
});
test("a new it.skip is a false heal", () => {
  assert.match(falseHeals(fixture("it-skip"), CI_FIXER).join("\n"), /new skip/);
});
test("a lower fail_under is a false heal", () => {
  assert.deepEqual(falseHeals(fixture("fail-under"), CI_FIXER), ["cloud/rhinoCloud/pyproject.toml: fail_under loosened 50 -> 40"]);
});
test("a sleep added by the flaky-test fixer is a false heal", () => {
  assert.match(falseHeals(fixture("sleep"), FLAKY_FIXER).join("\n"), /retry or sleep added/);
});
